export interface Book {
  id: string;
  slug: string;
  titleBn: string;
  titleEn: string;
  classLevel: string; // e.g., 'class-1', 'class-6', 'class-12'
  classNameBn: string; // e.g., '১ম শ্রেণি', '৬ষ্ঠ শ্রেণি'
  category: 'primary' | 'secondary' | 'ibtedai' | 'dakhil' | 'college' | 'guide';
  categoryBn: string;
  medium: 'bangla' | 'english';
  mediumBn: string;
  year: number; // 2026, 2027
  fileSizeBytes: string;
  pageCount: number;
  downloadUrl: string;
  driveUrl?: string;
  descriptionBn: string;
  source_name: string;
  source_url: string;
  last_verified: string;
  publisher: string;
  isPublished?: boolean;
  statusText?: string;
}

export interface NoticeItem {
  id: string;
  slug: string;
  title: string;
  category: 'notice' | 'routine' | 'result' | 'syllabus';
  categoryBn: string;
  date: string;
  lastUpdated?: string;
  isNew?: boolean;
  linkText: string;
  summary: string;
  officialSource?: string;
  officialSourceName?: string;
  buyUrl?: string;
  buyUrlName?: string;
  pdfUrl?: string;
  content?: string;
  faq?: { q: string; a: string }[];
}

