// Helper queries for clean Next.js Pages & SEO
export function getBookByClassAndSlug(classLevel: string, slug: string): Book | undefined {
  return BOOKS_DATA.find((b) => b.classLevel === classLevel && b.slug === slug);
}

export function getBooksByClass(classLevel: string, year?: number): Book[] {
  return BOOKS_DATA.filter((b) => b.classLevel === classLevel && (year ? b.year === year : true));
}

export function getBooksByYear(year: number): Book[] {
  return BOOKS_DATA.filter((b) => b.year === year);
}

export function getNoticeBySlug(slug: string): NoticeItem | undefined {
  return NOTICES_DATA.find((n) => n.slug === slug);
}

/**
 * H3 — disambiguator for books that share (classLevel, year, titleBn).
 * 72 such groups (144 books) exist in the data. The suffix is always a
 * REAL property of the record, never invented:
 * - medium differs (Bangla medium vs English version): the English-version
 *   record gets " (ইংরেজি সংস্করণ)", the Bangla-medium one keeps the plain title.
 * - same title, same medium: the records are two different files of the same
 *   book and differ in the data only by page count (and file size), so the
 *   page count — a real property of each file — distinguishes them.
 */
export function getBookTitleSuffix(book: Book): string {
  const peers = BOOKS_DATA.filter(
    (b) => b.classLevel === book.classLevel && b.year === book.year && b.titleBn === book.titleBn
  );
  if (peers.length <= 1) return '';
  if (peers.some((b) => b.medium !== book.medium)) {
    return book.medium === 'english' ? ' (ইংরেজি সংস্করণ)' : '';
  }
  return ` (${book.pageCount} পৃষ্ঠা)`;
}

export function getBookDisplayTitleBn(book: Book): string {
  return `${book.titleBn}${getBookTitleSuffix(book)}`;
}

/** M2 — truncate an emitted meta description to ~155 chars, at a word boundary. */
export function truncateMetaDescription(text: string, maxLength = 155): string {
  const clean = text.replace(/\s+/g, ' ').trim();
  if (clean.length <= maxLength) return clean;
  const cut = clean.slice(0, maxLength - 1);
  const lastSpace = cut.lastIndexOf(' ');
  const base = lastSpace > 100 ? cut.slice(0, lastSpace) : cut;
  return `${base.trim()}…`;
}

/**
 * Intelligent token-based Bangla/English search parser
 * Handles queries like "ষষ্ঠ শ্রেণির বাংলা", "class 6 math", "৯ম শ্রেণি বিজ্ঞান", "দাখিল ৭ম শ্রেণি", "HSC বাংলা", "২০২৫ class 5"
 */
export function searchBooks(
  books: Book[],
  query: string,
  options?: { year?: number; category?: string; classLevel?: string }
): Book[] {
  let list = books;

  if (options?.year) {
    list = list.filter((b) => b.year === options.year);
  }
  if (options?.category && options.category !== 'all') {
    list = list.filter((b) => b.category === options.category);
  }
  if (options?.classLevel && options.classLevel !== 'all') {
    list = list.filter((b) => b.classLevel === options.classLevel);
  }

  const rawQuery = query.trim().toLowerCase();
  if (!rawQuery) return list;

  // Bengali numerals to digits mapping
  const bnToEnMap: Record<string, string> = {
    '০': '0', '১': '1', '২': '2', '৩': '3', '৪': '4',
    '৫': '5', '৬': '6', '৭': '7', '৮': '8', '৯': '9',
  };
  const normalizedDigits = rawQuery.replace(/[০-৯]/g, (char) => bnToEnMap[char] || char);

  // Class detection patterns
  const classPatterns: { pattern: RegExp; targetClass: string }[] = [
    { pattern: /(প্রথম|১ম|class[\s-]?1|grade[\s-]?1)\b/i, targetClass: 'class-1' },
    { pattern: /(দ্বিতীয়|দ্বিতীয়|২য়|২য়|class[\s-]?2|grade[\s-]?2)\b/i, targetClass: 'class-2' },
    { pattern: /(তৃতীয়|তৃতীয়|৩য়|৩য়|class[\s-]?3|grade[\s-]?3)\b/i, targetClass: 'class-3' },
    { pattern: /(চতুর্থ|৪র্থ|class[\s-]?4|grade[\s-]?4)\b/i, targetClass: 'class-4' },
    { pattern: /(পঞ্চম|৫ম|class[\s-]?5|grade[\s-]?5)\b/i, targetClass: 'class-5' },
    { pattern: /(ষষ্ঠ|৬ষ্ঠ|class[\s-]?6|grade[\s-]?6)\b/i, targetClass: 'class-6' },
    { pattern: /(সপ্তম|৭ম|class[\s-]?7|grade[\s-]?7)\b/i, targetClass: 'class-7' },
    { pattern: /(অষ্টম|৮ম|class[\s-]?8|grade[\s-]?8)\b/i, targetClass: 'class-8' },
    { pattern: /(নবম|৯ম|class[\s-]?9|grade[\s-]?9)\b/i, targetClass: 'class-9' },
    { pattern: /(দশম|১০ম|class[\s-]?10|grade[\s-]?10)\b/i, targetClass: 'class-10' },
    { pattern: /(একাদশ|১১শ|class[\s-]?11|grade[\s-]?11|hsc|এইচএসসি)\b/i, targetClass: 'class-11' },
    { pattern: /(দ্বাদশ|১২শ|class[\s-]?12|grade[\s-]?12)\b/i, targetClass: 'class-12' },
  ];

  let detectedClass: string | null = null;
  for (const item of classPatterns) {
    if (item.pattern.test(rawQuery) || item.pattern.test(normalizedDigits)) {
      detectedClass = item.targetClass;
      break;
    }
  }

  // Tokenize query into meaningful search words (removing common noise words)
  const stopWords = new Set(['শ্রেণি', 'শ্রেণির', 'শ্রেনী', 'শ্রেনীর', 'এর', 'বই', 'pdf', 'বইয়ের', 'পাঠ্যবই', 'class', 'grade']);
  const tokens = normalizedDigits
    .split(/[\s,+/_-]+/)
    .filter((t) => t.length > 0 && !stopWords.has(t));

  return list.filter((book) => {
    // If a specific class was detected in the user prompt, check if the book matches
    if (detectedClass) {
      // If prompt has HSC, it can be class-11 or class-12
      if (detectedClass === 'class-11' && (rawQuery.includes('hsc') || rawQuery.includes('এইচএসসি'))) {
        if (book.classLevel !== 'class-11' && book.classLevel !== 'class-12') return false;
      } else if (book.classLevel !== detectedClass) {
        return false;
      }
    }

    if (tokens.length === 0) return true;

    // Searchable text corpus for this book
    const searchable = [
      book.titleBn,
      book.titleEn,
      book.classNameBn,
      book.classLevel,
      book.categoryBn,
      book.mediumBn,
      book.medium,
      book.year.toString(),
      book.year === 2026 ? '২০২৬' : book.year === 2027 ? '২০২৭' : '২০২৫',
      book.category === 'dakhil' ? 'দাখিল dakhil' : '',
      book.category === 'ibtedai' ? 'ইবতেদায়ি ইবতেদায়ী ibtedai' : '',
    ].join(' ').toLowerCase();

    // Check tokens (excluding tokens that were part of class identification)
    const contentTokens = tokens.filter((t) => {
      if (detectedClass && (t === detectedClass || t.replace('class-', '') === detectedClass.replace('class-', ''))) {
        return false;
      }
      return true;
    });

    if (contentTokens.length === 0) return true;

    // Every remaining content token should match somewhere in the book's metadata
    return contentTokens.every((token) => {
      // Check direct inclusion or common subject aliases
      if (searchable.includes(token)) return true;
      if (token === 'math' && (searchable.includes('গণিত') || searchable.includes('mathematics'))) return true;
      if (token === 'গণিত' && (searchable.includes('math') || searchable.includes('mathematics'))) return true;
      if (token === 'science' && (searchable.includes('বিজ্ঞান') || searchable.includes('science'))) return true;
      if (token === 'বিজ্ঞান' && (searchable.includes('science'))) return true;
      if (token === 'bangla' && searchable.includes('বাংলা')) return true;
      if (token === 'english' && (searchable.includes('ইংরেজি') || searchable.includes('english'))) return true;
      return false;
    });
  });
}

